document.addEventListener('click',function(e){var a=e.target.closest&&e.target.closest('a[href="#p-politicas"]');if(!a)return;var t=(a.textContent||'').toLowerCase(),id=/privacidade/.test(t)?'privacidade':/cookie/.test(t)?'cookies':/troca|devolu|desist/.test(t)?'trocas':/envio|entrega|frete/.test(t)?'envio':/termo/.test(t)?'termos':/aviso/.test(t)?'aviso-legal':'';if(!id)return;setTimeout(function(){var d=document.getElementById(id);if(d){d.open=true;d.scrollIntoView({block:'start'})}},80)});
(function(){var d=document.querySelectorAll('.idf-acc details');d.forEach(function(x){x.addEventListener('toggle',function(){if(x.open)d.forEach(function(y){if(y!==x)y.open=false})})})})();
